begin;

create table tongs.reference_clip_plan_revisions(
 id uuid primary key default gen_random_uuid(), workspace_id uuid not null references tongs.workspaces(id), workpiece_id uuid not null,
 revision bigint not null check(revision>0), previous_revision_id uuid, previous_revision bigint,
 script_approval_id uuid not null, script_approval_revision bigint not null, script_content_hash text not null check(script_content_hash~'^[0-9a-f]{64}$'),
 contract_version text not null, content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'),
 created_by uuid not null, created_at timestamptz not null default now(),
 unique(id,workspace_id,workpiece_id,revision), unique(workspace_id,workpiece_id,revision),
 foreign key(workpiece_id,workspace_id) references tongs.episodes(id,workspace_id),
 foreign key(previous_revision_id,workspace_id,workpiece_id,previous_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision),
 foreign key(script_approval_id,workspace_id,workpiece_id,script_approval_revision) references tongs.script_approval_revisions(id,workspace_id,workpiece_id,approval_revision)
);
create table tongs.reference_clip_plan_sequences(
 workspace_id uuid not null, workpiece_id uuid not null, current_plan_revision_id uuid, current_plan_revision bigint not null default 0,
 current_selection_revision bigint not null default 0, updated_at timestamptz not null default now(), primary key(workspace_id,workpiece_id),
 foreign key(workpiece_id,workspace_id) references tongs.episodes(id,workspace_id),
 foreign key(current_plan_revision_id,workspace_id,workpiece_id,current_plan_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision)
);
create table tongs.reference_clip_opportunity_revisions(
 id uuid primary key default gen_random_uuid(), opportunity_id uuid not null, workspace_id uuid not null, workpiece_id uuid not null,
 revision bigint not null check(revision>0), previous_revision_id uuid, previous_revision bigint,
 source_plan_revision_id uuid not null, source_plan_revision bigint not null, script_approval_id uuid not null, script_approval_revision bigint not null,
 source_id uuid not null, source_revision_id uuid not null, source_revision bigint not null,
 workpiece_source_link_id uuid not null, workpiece_source_link_revision_id uuid not null, workpiece_source_link_revision bigint not null,
 context_before text not null default '', context_focus text not null check(length(btrim(context_focus))>0), context_after text not null default '',
 citation_anchor_json jsonb not null default '{}'::jsonb, media_range_json jsonb not null default '{}'::jsonb,
 narrative_purpose text not null, placement_hint text not null, duration_target_ms bigint not null check(duration_target_ms>0), creator_direction text,
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'), created_by uuid not null, created_at timestamptz not null default now(),
 unique(id,workspace_id,workpiece_id,opportunity_id,revision), unique(workspace_id,workpiece_id,opportunity_id,revision),
 foreign key(source_plan_revision_id,workspace_id,workpiece_id,source_plan_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision),
 foreign key(previous_revision_id,workspace_id,workpiece_id,opportunity_id,previous_revision) references tongs.reference_clip_opportunity_revisions(id,workspace_id,workpiece_id,opportunity_id,revision),
 foreign key(source_revision_id,workspace_id,source_id,source_revision) references tongs.source_revisions(id,workspace_id,source_id,revision),
 foreign key(workpiece_source_link_revision_id,workspace_id,workpiece_id,workpiece_source_link_id,workpiece_source_link_revision) references tongs.workpiece_source_link_revisions(id,workspace_id,workpiece_id,link_id,revision)
);
create table tongs.reference_clip_plan_membership(
 plan_revision_id uuid not null, workspace_id uuid not null, workpiece_id uuid not null, plan_revision bigint not null, ordinal integer not null check(ordinal>0),
 opportunity_id uuid not null, opportunity_revision_id uuid not null, opportunity_revision bigint not null,
 primary key(plan_revision_id,ordinal), unique(plan_revision_id,opportunity_id),
 foreign key(plan_revision_id,workspace_id,workpiece_id,plan_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision),
 foreign key(opportunity_revision_id,workspace_id,workpiece_id,opportunity_id,opportunity_revision) references tongs.reference_clip_opportunity_revisions(id,workspace_id,workpiece_id,opportunity_id,revision)
);
create table tongs.reference_clip_candidates(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,workpiece_id uuid not null,opportunity_id uuid not null,created_by uuid not null,created_at timestamptz not null default now(),unique(id,workspace_id,workpiece_id,opportunity_id));
create table tongs.reference_clip_candidate_revisions(
 id uuid primary key default gen_random_uuid(),candidate_id uuid not null,workspace_id uuid not null,workpiece_id uuid not null,opportunity_id uuid not null,revision bigint not null check(revision>0),
 opportunity_revision_id uuid not null,opportunity_revision bigint not null,source_revision_id uuid not null,source_revision bigint not null,workpiece_source_link_revision_id uuid not null,workpiece_source_link_revision bigint not null,
 asset_id uuid not null,asset_content_hash text not null check(asset_content_hash~'^[0-9a-f]{64}$'),asset_path text not null,storage_bucket text not null,storage_key text not null,mime_type text not null check(mime_type like 'video/%'),duration_ms bigint not null check(duration_ms>0),poster_asset_id uuid,
 rights_basis text not null check(rights_basis in('creator_owned','licensed','public_domain','permission_granted','fair_use_claim','unknown')),
 rights_holder text,license_identifier text,license_url text,territories text[],expires_at timestamptz,attribution_required boolean not null default false,attribution_text text,
 rights_evidence_json jsonb not null default '{}'::jsonb,provenance_json jsonb not null default '{}'::jsonb,
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'),created_by uuid not null,created_at timestamptz not null default now(),
 unique(id,workspace_id,workpiece_id,opportunity_id,revision),unique(candidate_id,revision),
 foreign key(candidate_id,workspace_id,workpiece_id,opportunity_id) references tongs.reference_clip_candidates(id,workspace_id,workpiece_id,opportunity_id),
 foreign key(opportunity_revision_id,workspace_id,workpiece_id,opportunity_id,opportunity_revision) references tongs.reference_clip_opportunity_revisions(id,workspace_id,workpiece_id,opportunity_id,revision),
 foreign key(source_revision_id) references tongs.source_revisions(id),foreign key(workpiece_source_link_revision_id) references tongs.workpiece_source_link_revisions(id),foreign key(asset_id) references tongs.assets(id),foreign key(poster_asset_id) references tongs.assets(id)
);
create table tongs.reference_clip_selections(
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null,workpiece_id uuid not null,revision bigint not null check(revision>0),previous_selection_id uuid,previous_revision bigint,
 plan_revision_id uuid not null,plan_revision bigint not null,opportunity_id uuid not null,opportunity_revision_id uuid not null,opportunity_revision bigint not null,candidate_revision_id uuid not null,candidate_revision bigint not null,
 operation_id text not null,operation_fingerprint text not null check(operation_fingerprint~'^[0-9a-f]{64}$'),created_by uuid not null,created_at timestamptz not null default now(),unique(workspace_id,workpiece_id,revision),unique(operation_id),
 foreign key(plan_revision_id,workspace_id,workpiece_id,plan_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision),foreign key(candidate_revision_id) references tongs.reference_clip_candidate_revisions(id)
);
create table tongs.reference_clip_operation_receipts(
 operation_id text primary key,operation_fingerprint text not null check(operation_fingerprint~'^[0-9a-f]{64}$'),operation_type text not null check(operation_type in('plan_commit','candidate_commit','selection')),
 workspace_id uuid not null,workpiece_id uuid not null,opportunity_id uuid,state text not null check(state in('committed','selected')),normalized_inputs_json jsonb not null default '{}'::jsonb,
 result_plan_revision_id uuid,result_candidate_revision_id uuid,result_selection_id uuid,receipt_json jsonb not null,created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);

create or replace function tongs.reject_reference_clip_immutable_mutation() returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin raise exception 'reference clip canonical revisions are immutable' using errcode='55000';end$$;
do $$declare n text;begin foreach n in array array['reference_clip_plan_revisions','reference_clip_opportunity_revisions','reference_clip_plan_membership','reference_clip_candidates','reference_clip_candidate_revisions','reference_clip_selections','reference_clip_operation_receipts'] loop execute format('create trigger %I before update or delete on tongs.%I for each row execute function tongs.reject_reference_clip_immutable_mutation()',n||'_immutable',n);end loop;end$$;

create or replace function tongs.commit_reference_clip_plan(p_workspace_id uuid,p_workpiece_id uuid,p_expected_revision_id uuid,p_expected_revision bigint,p_script_approval_id uuid,p_contract_version text,p_opportunities jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare s tongs.reference_clip_plan_sequences%rowtype; a tongs.script_approval_revisions%rowtype; p tongs.reference_clip_plan_revisions%rowtype; o jsonb; r tongs.reference_clip_opportunity_revisions%rowtype; prev tongs.reference_clip_opportunity_revisions%rowtype; src tongs.source_revisions%rowtype; lnk tongs.workpiece_source_link_revisions%rowtype; oid uuid; h text; ih text; i int:=0; prior jsonb; result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;
 select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;
 if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if jsonb_typeof(p_opportunities)<>'array' then return jsonb_build_object('disposition','opportunities_required');end if;
 insert into tongs.reference_clip_plan_sequences(workspace_id,workpiece_id) values(p_workspace_id,p_workpiece_id) on conflict do nothing;select * into s from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if s.current_plan_revision<>p_expected_revision or s.current_plan_revision_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','plan_revision_conflict','current_revision_id',s.current_plan_revision_id,'current_revision',s.current_plan_revision);end if;
 select * into a from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;if not found then return jsonb_build_object('disposition','script_revision_conflict');end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('script',a.script_content_hash,'contract',p_contract_version,'opportunities',p_opportunities)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'revision',s.current_plan_revision+1,'previous',s.current_plan_revision_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by) values(p_workspace_id,p_workpiece_id,s.current_plan_revision+1,s.current_plan_revision_id,nullif(s.current_plan_revision,0),a.id,a.approval_revision,a.script_content_hash,p_contract_version,h,ih,p_actor_id) returning * into p;
 for o in select value from jsonb_array_elements(p_opportunities) loop
  i:=i+1;oid:=coalesce(nullif(o->>'opportunity_id','')::uuid,gen_random_uuid());select * into src from tongs.source_revisions where id=(o->>'source_revision_id')::uuid and workspace_id=p_workspace_id;select * into lnk from tongs.workpiece_source_link_revisions where id=(o->>'workpiece_source_link_revision_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;if src.id is null or lnk.id is null then raise exception 'exact Source revision and workpiece link required';end if;
  select * into prev from tongs.reference_clip_opportunity_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=oid order by revision desc limit 1;
  h:=encode(extensions.digest(convert_to(o::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'plan',p.id,'opportunity',oid,'revision',coalesce(prev.revision,0)+1)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_id,source_revision_id,source_revision,workpiece_source_link_id,workpiece_source_link_revision_id,workpiece_source_link_revision,context_before,context_focus,context_after,citation_anchor_json,media_range_json,narrative_purpose,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
  values(oid,p_workspace_id,p_workpiece_id,coalesce(prev.revision,0)+1,prev.id,prev.revision,p.id,p.revision,a.id,a.approval_revision,src.source_id,src.id,src.revision,lnk.link_id,lnk.id,lnk.revision,coalesce(o->>'context_before',''),o->>'context_focus',coalesce(o->>'context_after',''),coalesce(o->'citation_anchor','{}'),coalesce(o->'media_range','{}'),o->>'narrative_purpose',o->>'placement_hint',coalesce((o->>'duration_target_ms')::bigint,5000),o->>'creator_direction',h,ih,p_actor_id) returning * into r;
  insert into tongs.reference_clip_plan_membership values(p.id,p_workspace_id,p_workpiece_id,p.revision,i,oid,r.id,r.revision);
 end loop;
 update tongs.reference_clip_plan_sequences set current_plan_revision_id=p.id,current_plan_revision=p.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','plan_revision',to_jsonb(p));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,state,result_plan_revision_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'plan_commit',p_workspace_id,p_workpiece_id,'committed',p.id,result,p_actor_id);return result;
end$$;

create or replace function tongs.commit_reference_clip_candidate(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_opportunity_revision_id uuid,p_asset_id uuid,p_poster_asset_id uuid,p_rights jsonb,p_provenance jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare seq tongs.reference_clip_plan_sequences%rowtype;o tongs.reference_clip_opportunity_revisions%rowtype;a tongs.assets%rowtype;poster tongs.assets%rowtype;c tongs.reference_clip_candidates%rowtype;r tongs.reference_clip_candidate_revisions%rowtype;h text;ih text;prior jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;perform 1 from tongs.reference_clip_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id and opportunity_revision_id=p_opportunity_revision_id;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;select * into o from tongs.reference_clip_opportunity_revisions where id=p_opportunity_revision_id;
 select * into a from tongs.assets where id=p_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='ready' and ready_at is not null and content_hash is not null and mime_type like 'video/%';if not found then return jsonb_build_object('disposition','verified_video_asset_required');end if;
 if p_poster_asset_id is not null then select * into poster from tongs.assets where id=p_poster_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='ready' and mime_type like 'image/%';if not found then return jsonb_build_object('disposition','verified_poster_asset_required');end if;end if;
 if coalesce(p_rights->>'basis','unknown')='unknown' then return jsonb_build_object('disposition','rights_evidence_required');end if;
 insert into tongs.reference_clip_candidates(workspace_id,workpiece_id,opportunity_id,created_by) values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_actor_id) returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset',a.content_hash,'source',o.source_revision_id,'link',o.workpiece_source_link_revision_id,'rights',p_rights,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'hash',h,'revision',1)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,poster_asset_id,rights_basis,rights_holder,license_identifier,license_url,territories,expires_at,attribution_required,attribution_text,rights_evidence_json,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(c.id,p_workspace_id,p_workpiece_id,p_opportunity_id,1,o.id,o.revision,o.source_revision_id,o.source_revision,o.workpiece_source_link_revision_id,o.workpiece_source_link_revision,a.id,a.content_hash,a.path,a.storage_bucket,a.storage_key,a.mime_type,coalesce((a.metadata_json->>'duration_ms')::bigint,1),poster.id,p_rights->>'basis',p_rights->>'rights_holder',p_rights->>'license_identifier',p_rights->>'license_url',array(select jsonb_array_elements_text(coalesce(p_rights->'territories','[]'))),nullif(p_rights->>'expires_at','')::timestamptz,coalesce((p_rights->>'attribution_required')::boolean,false),p_rights->>'attribution_text',p_rights,p_provenance,h,ih,p_actor_id) returning * into r;
 result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(r));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_candidate_revision_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'candidate_commit',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',r.id,result,p_actor_id);return result;
end$$;

create or replace function tongs.select_reference_clip_candidate(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_candidate_revision_id uuid,p_expected_plan_revision_id uuid,p_expected_plan_revision bigint,p_expected_selection_revision bigint,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare seq tongs.reference_clip_plan_sequences%rowtype;m tongs.reference_clip_plan_membership%rowtype;c tongs.reference_clip_candidate_revisions%rowtype;prev tongs.reference_clip_selections%rowtype;s tongs.reference_clip_selections%rowtype;prior jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;if seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;if seq.current_selection_revision<>p_expected_selection_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_selection_revision',seq.current_selection_revision);end if;
 select * into m from tongs.reference_clip_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;select * into c from tongs.reference_clip_candidate_revisions where id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and opportunity_revision_id=m.opportunity_revision_id;if not found then return jsonb_build_object('disposition','candidate_not_attached');end if;
 select * into prev from tongs.reference_clip_selections where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;insert into tongs.reference_clip_selections(workspace_id,workpiece_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,opportunity_id,opportunity_revision_id,opportunity_revision,candidate_revision_id,candidate_revision,operation_id,operation_fingerprint,created_by) values(p_workspace_id,p_workpiece_id,seq.current_selection_revision+1,prev.id,prev.revision,seq.current_plan_revision_id,seq.current_plan_revision,p_opportunity_id,m.opportunity_revision_id,m.opportunity_revision,c.id,c.revision,p_operation_id,p_operation_fingerprint,p_actor_id) returning * into s;update tongs.reference_clip_plan_sequences set current_selection_revision=s.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','selection',to_jsonb(s));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_selection_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'selection',p_workspace_id,p_workpiece_id,p_opportunity_id,'selected',s.id,result,p_actor_id);return result;
end$$;

create or replace function tongs.read_current_reference_clip_plan(p_workspace_id uuid,p_workpiece_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$select case when not tongs.has_workspace_role(p_workspace_id,'viewer') then null else(select jsonb_build_object('sequence',to_jsonb(s),'plan_revision',to_jsonb(p),'opportunities',coalesce((select jsonb_agg(jsonb_build_object('membership',to_jsonb(m),'opportunity_revision',to_jsonb(o),'source_revision',to_jsonb(sr),'source_link_revision',to_jsonb(lr),'candidates',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at) from tongs.reference_clip_candidate_revisions c where c.workspace_id=m.workspace_id and c.workpiece_id=m.workpiece_id and c.opportunity_id=m.opportunity_id and c.opportunity_revision_id=m.opportunity_revision_id),'[]'::jsonb),'selection',to_jsonb(sel)) order by m.ordinal) from tongs.reference_clip_plan_membership m join tongs.reference_clip_opportunity_revisions o on o.id=m.opportunity_revision_id join tongs.source_revisions sr on sr.id=o.source_revision_id join tongs.workpiece_source_link_revisions lr on lr.id=o.workpiece_source_link_revision_id left join lateral(select x.* from tongs.reference_clip_selections x where x.workspace_id=m.workspace_id and x.workpiece_id=m.workpiece_id and x.opportunity_id=m.opportunity_id and x.plan_revision_id=m.plan_revision_id order by x.revision desc limit 1)sel on true where m.plan_revision_id=s.current_plan_revision_id),'[]'::jsonb)) from tongs.reference_clip_plan_sequences s left join tongs.reference_clip_plan_revisions p on p.id=s.current_plan_revision_id where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id)end$$;
create or replace function tongs.read_reference_clip_visual_package(p_workspace_id uuid,p_workpiece_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$select case when not tongs.has_workspace_role(p_workspace_id,'viewer') then null else jsonb_build_object('contract_version','forge.reference-clips.hammer.v1','workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'clips',coalesce((select jsonb_agg(jsonb_build_object('opportunity_id',o.opportunity_id,'placement_hint',o.placement_hint,'duration_target_ms',o.duration_target_ms,'script_anchor',o.citation_anchor_json,'source_revision_id',c.source_revision_id,'source_link_revision_id',c.workpiece_source_link_revision_id,'candidate_revision_id',c.id,'asset_id',c.asset_id,'asset_content_hash',c.asset_content_hash,'asset_path',c.asset_path,'storage_bucket',c.storage_bucket,'storage_key',c.storage_key,'rights',c.rights_evidence_json,'provenance',c.provenance_json) order by m.ordinal) from tongs.reference_clip_plan_sequences q join tongs.reference_clip_plan_membership m on m.plan_revision_id=q.current_plan_revision_id join tongs.reference_clip_opportunity_revisions o on o.id=m.opportunity_revision_id join lateral(select x.* from tongs.reference_clip_selections x where x.workspace_id=q.workspace_id and x.workpiece_id=q.workpiece_id and x.opportunity_id=m.opportunity_id and x.plan_revision_id=q.current_plan_revision_id order by x.revision desc limit 1)s on true join tongs.reference_clip_candidate_revisions c on c.id=s.candidate_revision_id where q.workspace_id=p_workspace_id and q.workpiece_id=p_workpiece_id),'[]'::jsonb)) end$$;
create or replace function tongs.read_reference_clip_operation_receipt(p_workspace_id uuid,p_operation_id text) returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$select case when not tongs.has_workspace_role(p_workspace_id,'viewer') then null else(select to_jsonb(r) from tongs.reference_clip_operation_receipts r where r.workspace_id=p_workspace_id and r.operation_id=p_operation_id)end$$;

do $$declare n text;begin foreach n in array array['reference_clip_plan_revisions','reference_clip_plan_sequences','reference_clip_opportunity_revisions','reference_clip_plan_membership','reference_clip_candidates','reference_clip_candidate_revisions','reference_clip_selections','reference_clip_operation_receipts'] loop execute format('alter table tongs.%I enable row level security',n);execute format('create policy %I on tongs.%I for select to authenticated using(tongs.has_workspace_role(workspace_id,''viewer''))',n||'_viewer',n);execute format('revoke all on tongs.%I from public,anon,authenticated',n);execute format('grant select on tongs.%I to authenticated',n);end loop;end$$;
revoke all on function tongs.commit_reference_clip_plan(uuid,uuid,uuid,bigint,uuid,text,jsonb,text,text,uuid),tongs.commit_reference_clip_candidate(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,jsonb,text,text,uuid),tongs.select_reference_clip_candidate(uuid,uuid,uuid,uuid,uuid,bigint,bigint,text,text,uuid) from public,anon,authenticated;
grant execute on function tongs.commit_reference_clip_plan(uuid,uuid,uuid,bigint,uuid,text,jsonb,text,text,uuid),tongs.commit_reference_clip_candidate(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,jsonb,text,text,uuid),tongs.select_reference_clip_candidate(uuid,uuid,uuid,uuid,uuid,bigint,bigint,text,text,uuid),tongs.read_current_reference_clip_plan(uuid,uuid),tongs.read_reference_clip_visual_package(uuid,uuid),tongs.read_reference_clip_operation_receipt(uuid,text) to authenticated,service_role;
comment on table tongs.reference_clip_plan_revisions is 'Immutable script-relative reference-media opportunity plans; legacy cdc_plan is not authority.';
commit;
